import boto3
import os

def start_password_reset(email: str) -> dict:
    """
    Starts a password reset flow for a user with the given email using Amazon Cognito.
    """
    # Environment variables or configuration for AWS credentials and region
    # AWS_ACCESS_KEY_ID = os.environ.get("AWS_ACCESS_KEY_ID")
    # AWS_SECRET_ACCESS_KEY = os.environ.get("AWS_SECRET_ACCESS_KEY")
    AWS_REGION = os.environ.get("AWS_REGION", "us-east-1")
    USER_POOL_CLIENT_ID = os.environ.get("USER_POOL_CLIENT_ID", "your_cognito_user_pool_client_id") # Replace with your Cognito User Pool App Client ID

    client = boto3.client(
        'cognito-idp',
        region_name=AWS_REGION,
        # aws_access_key_id=AWS_ACCESS_KEY_ID, # Uncomment if not using IAM roles or default credential chain
        # aws_secret_access_key=AWS_SECRET_ACCESS_KEY
    )

    try:
        response = client.forgot_password(
            ClientId=USER_POOL_CLIENT_ID,
            Username=email
        )
        return {
            "success": True,
            "delivery_medium": response.get('CodeDeliveryDetails', {}).get('DeliveryMedium'),
            "destination": response.get('CodeDeliveryDetails', {}).get('Destination'),
            "attribute_name": response.get('CodeDeliveryDetails', {}).get('AttributeName')
        }
    except client.exceptions.UserNotFoundException:
        # It's often good security practice not to reveal whether a user exists
        # by returning a generic success message even if the user isn't found.
        # However, for debugging or specific application flows, you might choose to
        # re-raise or return a specific error.
        print(f"Password reset requested for {email} (user may or may not exist).")
        return {
            "success": False,
            "message": "If an account with that email exists, a password reset code has been sent."
        }
    except client.exceptions.LimitExceededException as e:
        return {"success": False, "message": f"Too many requests. Please try again later. Error: {str(e)}"}
    except Exception as e:
        return {"success": False, "message": f"An unexpected error occurred: {str(e)}"}
